ST.xhtml:p:
RTriggerMove(CLK := g_bLinearActuatorEnablM OR g_bLinearActuatorEnable OR bLinearActuatorEnable);
RTriggerStop(CLK := g_bLinearActuatorClose OR bLinearActuatorClose);
IF RTriggerMove.Q THEN
  nMoveTime:=LREAL_TO_DINT(g_dCircleRadius/dLinearActuatorVel);
  IF g_bLinearActuatorEnablM THEN
    g_bLinearActuatorEnablM := FALSE;
    bDirection:=LREAL_TO_BOOL(g_dLinearActuatorDirectionM);
    bLinearActuatorBeZero:=LREAL_TO_BOOL(g_dLinearActuatorBeZeroM);
    IF bLinearActuatorBeZero THEN
      nMoveTime:=LREAL_TO_DINT(dLinearActuatorLength/dLinearActuatorVel);
    END_IF;
    nLinearActuatorSwitch:=50;
  ELSIF g_bLinearActuatorEnable THEN
    bDirection := g_bLinearActuatorDirection;
    nLinearActuatorSwitch:=50;
  ELSIF bLinearActuatorEnable THEN
    bDirection := bLinearActuatorDirection;
    nLinearActuatorSwitch:=10;
  END_IF;

  bLinearActuatorEnable:=FALSE;
  g_bLinearActuatorEnable:=FALSE;
  TonMove(IN :=FALSE);

  g_boLinearActuatorForward:=FALSE;  
  g_boLinearActuatorBack:=FALSE;

  g_boLinearActuatorMoveDone:=FALSE;
END_IF;

IF RTriggerStop.Q THEN
  g_bLinearActuatorClose:=FALSE;
  bLinearActuatorClose:=FALSE;
  g_boLinearActuatorForward:=FALSE;
  g_boLinearActuatorBack:=FALSE;  
  g_boLinearActuatorMoveDone:=TRUE;
END_IF;

CASE nLinearActuatorSwitch OF
  0:
    nLinearActuatorSwitch:=0;
  10:(*手动控制*)
    IF bMaualType THEN
      nMoveTime:= LREAL_TO_DINT(dLinearActuatorLength/dLinearActuatorVel);
      nLinearActuatorSwitch:=50;
    ELSE
      IF bDirection THEN
        g_boLinearActuatorForward:=FALSE;
        g_boLinearActuatorBack:=TRUE;
      ELSE 
        g_boLinearActuatorForward:=TRUE;
        g_boLinearActuatorBack:=FALSE;
      END_IF;
      nLinearActuatorSwitch:=0;
    END_IF;
  50:
    IF bDirection THEN
      g_boLinearActuatorForward:=FALSE;
      g_boLinearActuatorBack:=TRUE;
    ELSE 
      g_boLinearActuatorForward:=TRUE;
      g_boLinearActuatorBack:=FALSE;
    END_IF;
    nLinearActuatorSwitch:=60;
  60:
    TonMove(IN :=TRUE,PT := DINT_TO_TIME(nMoveTime));
    IF TonMove.Q THEN
      TonMove(IN :=FALSE);
      g_boLinearActuatorForward:=FALSE;
      g_boLinearActuatorBack:=FALSE;  
      g_boLinearActuatorMoveDone:=TRUE;
      M.ENABLE[237] := 0;
      nLinearActuatorSwitch:=0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  g_boLinearActuatorForward:=FALSE;
  g_boLinearActuatorBack:=FALSE;
  g_boLinearActuatorMoveDone:=FALSE;
  nLinearActuatorSwitch:=0;
  TonMove(IN :=FALSE);
END_IF;
